$text: string.unquote("#{$display}");
@if not list.index($-container-displays, $text) and not fn-css-vars.is-css-var($display) {
    @error "container: #{meta.inspect($display)} is not a display value. Use one of #{$-container-displays} or var().";
}

display: $text;
@include container-base;

// Declarations before the nested @media rules (Sass 1.79 to 1.91 warn about declarations after nested rules)
@include container-padding(4);
@each $breakpoint, $width in config-breakpoint.$breakpoints {
    @media (min-width: $width) {
        // calc() keeps em and rem breakpoints valid; px widths simplify to a plain length
        max-width: calc($width - 100px);
    }
}

$min: fn-breakpoints.get-breakpoint-value($breakpoint);
$next-breakpoint: null;

@each $name, $width in config-breakpoint.$breakpoints {
    @if $width > $min and (not $next-breakpoint or $width < $next-breakpoint) {
        $next-breakpoint: $width;
    }
}

@if $next-breakpoint {
    @container #{$containerName} (min-width: #{$min}) and (max-width: #{fn-breakpoints.breakpoint-max($next-breakpoint)}) {
        @content;
    }
} @else {
    @container #{$containerName} (min-width: #{$min}) {
        @content;
    }
}

// Interpolated so an unquoted 2xl (the number 2 with unit xl) matches "2xl"
@if map.has-key(config-breakpoint.$breakpoints, "#{$bp}") {
    @return map.get(config-breakpoint.$breakpoints, "#{$bp}");
}
$bp: fn-math.css-arg($bp);
@if meta.type-of($bp) == "number" {
    @if math.is-unitless($bp) {
        @error "Invalid breakpoint: #{$bp} is not a breakpoint name (#{map.keys(config-breakpoint.$breakpoints)}). Write a unit for a custom width (#{$bp}px).";
    }
    @return $bp;
}
