$name: string.unquote("#{$color-name}");
@if not $shade and fn-tokens.has-token("text-on-#{$name}") {
    color: fn-tokens.token("text-on-#{$name}");
} @else {
    $renamed: fn-tokens.renamed-role($name);
    @if $renamed {
        @error "text-on-color(#{$name}): renamed in 2.0, use text-on-color(#{$renamed}).";
    }
    @if not $shade {
        $shade: 500;
    }
    $stop: $shade;
    @if meta.type-of($stop) == "string" {
        $stop: fn-math.to-number($stop);
    }
    @if not color-fn.is-valid-shade($stop) {
        @error "text-on-color(#{$name}, #{$shade}): invalid shade. Valid shades: #{config-color.$shade-stops}.";
    }
    @if not map.has-key(fn-tokens.color-scales(), $name) and fn-types.get-type($color-name) != "color" {
        @error "text-on-color(#{$name}): unknown color. Use a role (#{map.keys(config-color.$semantic-colors)}), a palette name (#{config-color.$primitive-color-names}) or a color value.";
    }

    color: color-fn.find-text-color(color-fn.get-color($color-name, $stop));
}

