$animation-name: -keyframes-name(anim-shake-#{$intensity});

animation: #{$animation-name} $duration $timing $iteration;

@include ensure-keyframes($animation-name) {
    0%,
    100% {
        transform: translateX(0);
    }

    10%,
    30%,
    50%,
    70%,
    90% {
        transform: translateX(-$intensity);
    }

    20%,
    40%,
    60%,
    80% {
        transform: translateX($intensity);
    }
}

$defaults: (
    vertical: 0.5rem,
    horizontal: 0,
    duration: 1s,
    timing: ease-in-out,
    iteration: infinite,
);

// Merge with defaults
$props: -props("animate-bounce", $defaults, $props);
$x: -offset("animate-bounce", "horizontal", map.get($props, "horizontal"));
$y: -offset("animate-bounce", "vertical", map.get($props, "vertical"));
$duration: map.get($props, "duration");
$easing: map.get($props, "timing");
$iteration: map.get($props, "iteration");

// Handle units
$x-unit: "-";
@if $x {
    $x-unit: fn-units.safe-unit-name(math.unit($x));
}
$y-unit: "-";
@if $y {
    $y-unit: fn-units.safe-unit-name(math.unit($y));
}

// Clean values (remove units)
$clean-x: 0;
@if $x {
    $clean-x: fn-units.strip-unit($x);
}
$clean-y: 0;
@if $y {
    $clean-y: fn-units.strip-unit($y);
}

$animation-name: -keyframes-name(anim-bounce-#{$clean-x}#{$x-unit}-#{$clean-y}#{$y-unit});

// Apply the animation
animation: #{$animation-name} $duration $easing $iteration;

// Generate keyframes with ensure-keyframes pattern
@include ensure-keyframes($animation-name) {
    0%,
    100% {
        transform: translate(0, 0);
        animation-timing-function: cubic-bezier(0.8, 0, 1, 1);
    }

    50% {
        transform: translate($x, $y);
        animation-timing-function: cubic-bezier(0, 0, 0.2, 1);
    }
}

transition-property: all;
transition-duration: fn-css-vars.scale-var("duration", config-transitions.$durations, config-transitions.$transition-default-duration);
transition-timing-function: fn-css-vars.scale-var("ease", config-transitions.$timing-functions, config-transitions.$transition-default-ease);

$defaults: (
    min-opacity: 0.5,
    max-opacity: 1,
    duration: 1s,
    timing: ease-in-out,
    iteration: infinite,
);

// Merge with defaults
$props: -props("animate-pulse", $defaults, $props);
$min-opacity: map.get($props, "min-opacity");
$max-opacity: map.get($props, "max-opacity");
$duration: map.get($props, "duration");
$timing: map.get($props, "timing");
$iteration: map.get($props, "iteration");

$animation-name: -keyframes-name(anim-pulse-#{$min-opacity * 100}-#{$max-opacity * 100});

animation: #{$animation-name} $duration $timing $iteration;

@include ensure-keyframes($animation-name) {
    0%,
    100% {
        opacity: $max-opacity;
    }

    50% {
        opacity: $min-opacity;
    }
}

$defaults: (
    direction: normal,
    duration: 1s,
    timing: linear,
    iteration: infinite,
);

// Merge with defaults
$props: -props("animate-spin", $defaults, $props);
$direction: map.get($props, "direction");
$duration: map.get($props, "duration");
$timing: map.get($props, "timing");
$iteration: map.get($props, "iteration");

$animation-name: anim-spin-#{$direction};

animation: #{$animation-name} $duration $timing $iteration;

@include ensure-keyframes($animation-name) {
    from {
        transform: rotate(0deg);
    }

    to {
        @if $direction == "normal" {
            transform: rotate(360deg);
        } @else {
            transform: rotate(-360deg);
        }
    }
}

$defaults: (
    scale: 2,
    duration: 1s,
    timing: cubic-bezier(0, 0, 0.2, 1),
    iteration: infinite,
);

// Merge with defaults
$props: -props("animate-ping", $defaults, $props);
$scale: map.get($props, "scale");
$duration: map.get($props, "duration");
$timing: map.get($props, "timing");
$iteration: map.get($props, "iteration");
@if meta.type-of($scale) != "number" or not math.is-unitless($scale) {
    @error "animate-ping(): scale #{meta.inspect($scale)} is not a number. Write a unitless scale factor such as 2 or 1.5.";
}

$animation-name: -keyframes-name(anim-ping-#{$scale * 10});

animation: #{$animation-name} $duration $timing $iteration;

@include ensure-keyframes($animation-name) {
    75%,
    100% {
        transform: scale($scale);
        opacity: 0;
    }
}

$defaults: (
    type: in,
    duration: 0.5s,
    timing: ease-in-out,
    iteration: 1 forwards,
);

// Merge with defaults
$props: -props("animate-fade", $defaults, $props);
$type: map.get($props, "type");
$duration: map.get($props, "duration");
$timing: map.get($props, "timing");
$iteration: map.get($props, "iteration");

@if not list.index((in, out, in-up, in-down), $type) {
    @error "animate-fade(): unknown type #{$type}. Use in, out, in-up or in-down.";
}
$animation-name: anim-fade-#{$type};

animation: #{$animation-name} $duration $timing $iteration;

@include ensure-keyframes($animation-name) {
    @if $type == "in" {
        from {
            opacity: 0;
        }

        to {
            opacity: 1;
        }
    } @else if $type == "out" {
        from {
            opacity: 1;
        }

        to {
            opacity: 0;
        }
    } @else if $type == "in-up" {
        from {
            opacity: 0;
            transform: translateY(20px);
        }

        to {
            opacity: 1;
            transform: translateY(0);
        }
    } @else if $type == "in-down" {
        from {
            opacity: 0;
            transform: translateY(-20px);
        }

        to {
            opacity: 1;
            transform: translateY(0);
        }
    }
}

$defaults: (
    intensity: 5px,
    duration: 0.5s,
    timing: ease-in-out,
    iteration: 1,
);

// Merge with defaults
$props: -props("animate-shake", $defaults, $props);
$intensity: -offset("animate-shake", "intensity", map.get($props, "intensity"));
$duration: map.get($props, "duration");
$timing: map.get($props, "timing");
$iteration: map.get($props, "iteration");

$animation-name: -keyframes-name(anim-shake-#{$intensity});

animation: #{$animation-name} $duration $timing $iteration;

@include ensure-keyframes($animation-name) {
    0%,
    100% {
        transform: translateX(0);
    }

    10%,
    30%,
    50%,
    70%,
    90% {
        transform: translateX(-$intensity);
    }

    20%,
    40%,
    60%,
    80% {
        transform: translateX($intensity);
    }
}

$suffix: "";
@if $breakpoint {
    $suffix: "\\@#{$breakpoint}";
}

// Base layer class. The identity values sit in :where() (no specificity), so .backdrop-layer@md does not reset
// a variable set by .backdrop-blur-md
#{config-flags.$parent-selector} :where(.backdrop-layer#{$suffix}) {
    @include -backdrop-identity;
}
#{config-flags.$parent-selector} .backdrop-layer#{$suffix} {
    @include -backdrop-compose;
}

// Basic backdrop utilities
#{config-flags.$parent-selector} .backdrop-none#{$suffix} {
    @include backdrop-none;
}

// Blur utilities
@each $key, $value in $backdrop-blur-values {
    #{config-flags.$parent-selector} .backdrop-blur-#{$key}#{$suffix} {
        @include backdrop-blur($key);
    }
}

// Brightness utilities
@each $key, $value in $backdrop-brightness-values {
    #{config-flags.$parent-selector} .backdrop-brightness-#{$key}#{$suffix} {
        @include backdrop-brightness($key);
    }
}

// Contrast utilities
@each $key, $value in $backdrop-contrast-values {
    #{config-flags.$parent-selector} .backdrop-contrast-#{$key}#{$suffix} {
        @include backdrop-contrast($key);
    }
}

